#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <pthread.h>

#define MAX_POOL_SIZE 8
#define MAX_URL_LEN 512
#define ALLOWED_HOSTS_COUNT 3

typedef struct {
    CURL *handle;
    int in_use;
    char bound_host[256];
} PoolEntry;

typedef struct {
    PoolEntry entries[MAX_POOL_SIZE];
    pthread_mutex_t lock;
    int count;
} ConnectionPool;

static ConnectionPool g_pool = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

static const char *allowed_hosts[] = {
    "artifacts.internal.corp",
    "registry.internal.corp",
    "builds.internal.corp"
};

/* Normalize hostname: lowercase and strip trailing dot */
static void normalize_hostname(const char *input, char *output, size_t outlen) {
    size_t i = 0;
    size_t len = strlen(input);
    /* Strip trailing dot if present */
    if (len > 0 && input[len-1] == '.') len--;
    for (; i < len && i < outlen - 1; i++) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z') {
            output[i] = c + 32;
        } else {
            output[i] = c;
        }
    }
    output[i] = '\0';
}

/* Validate that a hostname is in the allowlist.
 * Uses byte-by-byte comparison after normalization.
 * This ensures only approved internal hosts are contacted. */
static int is_host_allowed(const char *hostname) {
    char normalized[256];
    normalize_hostname(hostname, normalized, sizeof(normalized));

    for (int i = 0; i < ALLOWED_HOSTS_COUNT; i++) {
        if (strcmp(normalized, allowed_hosts[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

/* Extract hostname from URL */
static int extract_host(const char *url, char *host, size_t hostlen) {
    const char *start = strstr(url, "://");
    if (!start) return -1;
    start += 3;
    const char *end = strchr(start, '/');
    if (!end) end = start + strlen(start);
    const char *port = strchr(start, ':');
    if (port && port < end) end = port;
    size_t len = end - start;
    if (len >= hostlen) return -1;
    memcpy(host, start, len);
    host[len] = '\0';
    return 0;
}

/* Acquire a connection from the pool, or create new one */
static CURL *pool_acquire(const char *host) {
    pthread_mutex_lock(&g_pool.lock);

    /* Look for existing idle connection to same host */
    for (int i = 0; i < g_pool.count; i++) {
        if (!g_pool.entries[i].in_use && 
            strcmp(g_pool.entries[i].bound_host, host) == 0) {
            g_pool.entries[i].in_use = 1;
            CURL *h = g_pool.entries[i].handle;
            pthread_mutex_unlock(&g_pool.lock);
            return h;
        }
    }

    /* Create new connection if pool not full */
    if (g_pool.count < MAX_POOL_SIZE) {
        CURL *h = curl_easy_init();
        if (h) {
            int idx = g_pool.count++;
            g_pool.entries[idx].handle = h;
            g_pool.entries[idx].in_use = 1;
            strncpy(g_pool.entries[idx].bound_host, host, 255);
            g_pool.entries[idx].bound_host[255] = '\0';
            pthread_mutex_unlock(&g_pool.lock);
            return h;
        }
    }

    pthread_mutex_unlock(&g_pool.lock);
    return NULL;
}

static void pool_release(CURL *handle) {
    pthread_mutex_lock(&g_pool.lock);
    for (int i = 0; i < g_pool.count; i++) {
        if (g_pool.entries[i].handle == handle) {
            g_pool.entries[i].in_use = 0;
            break;
        }
    }
    pthread_mutex_unlock(&g_pool.lock);
}

/* Download an artifact from the CI/CD artifact store.
 * Security: validates hostname against allowlist before connecting. */
int download_artifact(const char *artifact_url, const char *output_path) {
    char host[256];

    if (extract_host(artifact_url, host, sizeof(host)) != 0) {
        fprintf(stderr, "Invalid URL format\n");
        return -1;
    }

    if (!is_host_allowed(host)) {
        fprintf(stderr, "Host '%s' not in allowlist\n", host);
        return -1;
    }

    CURL *curl = pool_acquire(host);
    if (!curl) {
        fprintf(stderr, "Failed to acquire connection\n");
        return -1;
    }

    FILE *fp = fopen(output_path, "wb");
    if (!fp) {
        pool_release(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, artifact_url);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 5L);

    CURLcode res = curl_easy_perform(curl);
    fclose(fp);
    pool_release(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "Download failed: %s\n", curl_easy_strerror(res));
        unlink(output_path);
        return -1;
    }

    return 0;
}

/* CI pipeline step: fetch build dependencies */
int fetch_dependencies(const char *manifest_url) {
    char host[256];
    if (extract_host(manifest_url, host, sizeof(host)) != 0) return -1;
    if (!is_host_allowed(host)) return -1;

    /* Fetch manifest then process each dependency URL */
    CURL *curl = pool_acquire(host);
    if (!curl) return -1;

    /* In production this would parse the manifest and download deps */
    curl_easy_setopt(curl, CURLOPT_URL, manifest_url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    CURLcode res = curl_easy_perform(curl);
    pool_release(curl);

    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    curl_global_init(CURL_GLOBAL_DEFAULT);

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <artifact_url> <output_path>\n", argv[0]);
        return 1;
    }

    int ret = download_artifact(argv[1], argv[2]);

    curl_global_cleanup();
    return ret;
}
